// Command cherry-assets uploads Cherry's game-asset dataset to the R2 bucket that streaming serves
// (internal/assets). It only reads the dataset; the dataset is never written.
//
// The bucket's key layout is an invariant: static/ holds only the original files, read from the archive roots
// below, and every object Cherry makes lives under cherry/ (its indexes in cherry/manifest/, generated packs in
// cherry/garden/). The planner refuses anything else (checkOrigins), so an original can never be replaced by a
// generated file.
//
//	cherry-assets plan                 counts and bytes per category and item kind (no network)
//	cherry-assets upload               upload what is missing (HEAD, then PUT), then the indexes and the D1 mirror
//	cherry-assets upload -packs-only   upload only the map packs and cherry/manifest/packs.json (no bulk indexes, no D1 mirror)
//	cherry-assets verify               list the bucket and compare it with the plan; fails while legacy manifest/ keys remain
//	cherry-assets migrate-manifests    one-time: copy manifest/ to cherry/manifest/, then delete the legacy keys (no dataset)
//
// Credentials come from %LOCALAPPDATA%\Cherry\cloudflare.json and are never printed or logged. Logs go to
// %TEMP% (keys and sizes only).
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"sort"
	"strconv"
	"strings"

	"cherry/internal/assets"
	"cherry/internal/thumbs"
)

// defaultDataset is the santi backup, the first root: the bulk categories come from it alone.
const defaultDataset = `D:\Dev\projects\Cherry\.opencode\line-play-artifacts\santi-backup-20260921\jp.naver.lineplay.android\files`

// extraDataset is the lpbackup device backup. Only the items and map packs it has and santi lacks are added; its
// bulk categories are never read.
const extraDataset = `D:\Dev\projects\Cherry\.opencode\line-play-artifacts\lpbackup\jp.naver.lineplay.android\files`

// The two roots are fixed on purpose: both backups were taken before any device talked to Cherry, and the
// 2026-10-26 isolation audit found none of Cherry's generated bytes in them. A newer device backup holds files
// Cherry made at the client's own paths (item dp.png composites, the DailyBonus skin, files/animation/-cherry/),
// so adding one as a root needs a new audit; there is deliberately no flag for it.
var archiveRoots = []string{defaultDataset, extraDataset}

// chatActionPrefix is the version prefix of the chat action icons in the santi cache,
// cache/action/00005_chatting_deco_action_<name>.png. The client reads them under checkresource2 ch 00005, and
// Cherry serves them without the prefix.
const chatActionPrefix = "00005_"

// bulkSource maps a bulk category to its dataset folder. only, when set, limits the category to those
// files (paths relative to dir); subui is the one plist of UIResource, tx the string table.
type bulkSource struct {
	cat, dir string
	only     []string
}

var bulkSources = []bulkSource{
	{cat: "animation", dir: "animation"},
	{cat: "sound", dir: "sound"},
	{cat: "ui", dir: "UIResource"},
	{cat: "subui", dir: "UIResource", only: []string{"MarbleChallengePopup.plist"}},
	{cat: "tx", dir: "stringtable", only: []string{"arts_strings.ast"}},
}

// object is one R2 object to upload. Bulk objects also feed their category's index.
type object struct {
	key  string // static/<cat>/<rel>, static/item/<kind>/<id>/<rel>, static/<dir>/<name> (map pack), static/chatting/action_hd/<name>, static/garden01|craft01/<rel> (craft art), or cherry/... when generated
	path string // local file
	size int64
	cat  string // bulk category; "" for item and pack files
	pack string // map pack directory (garden or world); "" otherwise
	rel  string // path within the category or pack directory (bulk and packs only)
	md5  string // uppercase hex, set when the file is read by upload
	// generated marks a Cherry-made object: its key is under cherry/, its path is not an archive file, and recipe
	// names the generator and its sources (the D1 table generated). No generator exists yet.
	generated bool
	recipe    string
}

// buildObjects lists every object the server streams, sorted by key. roots are dataset folders in priority order.
// The bulk categories come from roots[0] alone, so the indexes describe that dataset. Items and map packs of a
// later root are added only where no earlier root has the same key; a duplicate within one root is an error.
// The result is checked by checkOrigins before anything is uploaded.
func buildObjects(roots []string) ([]*object, error) {
	var objs []*object
	have := map[string]bool{}
	for i, root := range roots {
		got, err := listRoot(root, i == 0)
		if err != nil {
			return nil, err
		}
		sort.Slice(got, func(a, b int) bool { return got[a].key < got[b].key })
		for j, o := range got {
			if j > 0 && o.key == got[j-1].key {
				return nil, fmt.Errorf("duplicate key %s", o.key)
			}
			if !have[o.key] {
				have[o.key] = true
				objs = append(objs, o)
			}
		}
	}
	sort.Slice(objs, func(i, j int) bool { return objs[i].key < objs[j].key })
	if err := checkOrigins(objs, roots); err != nil {
		return nil, err
	}
	return objs, nil
}

// checkOrigins enforces the key layout. An original (not generated) must have a static/ key and come from one of
// roots. A generated object must have a recipe, must not read an archive file, and must sit under cherry/ where
// its kind allows: a generated pack is cherry/garden/<name> (assets.GeneratedPackKey) and any other generated
// object stays out of cherry/manifest/, which holds the indexes.
func checkOrigins(objs []*object, roots []string) error {
	for _, o := range objs {
		if err := checkObject(o, roots); err != nil {
			return fmt.Errorf("%s (%s): %w", o.key, o.path, err)
		}
	}
	// A converted item is never a device-backup original: an original under static/item/ with the same kind and id
	// is refused (the converter skips every id a backup has, so this only trips on a stale tree).
	converted := map[string]bool{}
	for _, o := range objs {
		if o.generated {
			if ref := itemRef(o.key); ref != "" {
				converted[ref] = true
			}
		}
	}
	for _, o := range objs {
		if !o.generated && strings.HasPrefix(o.key, "static/item/") && converted[itemRef(o.key)] {
			return fmt.Errorf("%s (%s): a converted item is not an original", o.key, o.path)
		}
	}
	return nil
}

func checkObject(o *object, roots []string) error {
	if !o.generated {
		switch {
		case !strings.HasPrefix(o.key, "static/"):
			return errors.New("original outside static/")
		case !underAny(o.path, roots):
			return errors.New("original is not under an archive root")
		case cherryItemKey(o.key):
			return errors.New("Cherry-made item in a device backup is not an original")
		case strings.Contains(o.key, "/-cherry/") || strings.HasPrefix(path.Base(o.key), "cherry_day"):
			return errors.New("Cherry-made file (the -cherry/ probe or a cherry_day calendar tile) is not an original")
		}
		return nil
	}
	switch {
	case o.recipe == "":
		return errors.New("generated object has no recipe")
	case underAny(o.path, roots):
		return errors.New("generated object reads an archive file")
	case strings.HasPrefix(o.key, assets.CherryPrefix+"item/"):
		if len(strings.Split(o.key, "/")) != 5 || itemRef(o.key) == "" {
			return errors.New("generated item must be cherry/item/<kind>/<id>/<file>")
		}
	case o.pack != "":
		if o.pack != "garden" || o.key != assets.GeneratedPackKey(o.rel) {
			return fmt.Errorf("generated pack must be %s", assets.GeneratedPackKey(o.rel))
		}
	case !strings.HasPrefix(o.key, assets.CherryPrefix) || strings.HasPrefix(o.key, assets.ManifestPrefix):
		return fmt.Errorf("generated object must be under %s, outside %s", assets.CherryPrefix, assets.ManifestPrefix)
	}
	return nil
}

// cherryItemKey reports whether key is a static/item/<kind>/<id>/… file whose id is in Cherry's own block
// (assets.IsCherryItem): a generated item a device downloaded from Cherry, never ground truth.
func cherryItemKey(key string) bool {
	parts := strings.SplitN(strings.TrimPrefix(key, "static/item/"), "/", 3)
	if len(parts) < 3 || !strings.HasPrefix(key, "static/item/") {
		return false
	}
	id, err := strconv.ParseInt(parts[1], 10, 64)
	return err == nil && assets.IsCherryItem(id)
}

// underAny reports whether p is inside one of roots.
func underAny(p string, roots []string) bool {
	for _, r := range roots {
		rel, err := filepath.Rel(r, p)
		if err == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return true
		}
	}
	return false
}

// listRoot lists the objects of one dataset root. first marks the upload source: only it has bulk categories and
// chat icons, and it must have every folder. A later root without a folder (lpbackup has no world/) contributes
// nothing for it.
func listRoot(dataset string, first bool) ([]*object, error) {
	var objs []*object
	bulk := bulkSources
	if !first {
		bulk = nil
	}
	for _, src := range bulk {
		root := filepath.Join(dataset, src.dir)
		err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !d.Type().IsRegular() {
				return nil
			}
			rel := filepath.ToSlash(mustRel(root, p))
			if src.only != nil && !slices.Contains(src.only, rel) {
				return nil
			}
			info, err := d.Info()
			if err != nil {
				return err
			}
			objs = append(objs, &object{key: "static/" + src.cat + "/" + rel, path: p, size: info.Size(), cat: src.cat, rel: rel})
			return nil
		})
		if err != nil {
			return nil, fmt.Errorf("%s: %w", src.dir, err)
		}
	}
	// Map packs: the top-level <digits>.mworldpack files of garden and world. The extracted folders beside them
	// are not served.
	for _, dir := range assets.PackDirs {
		root := filepath.Join(dataset, dir)
		ents, err := os.ReadDir(root)
		if err != nil {
			if !first && errors.Is(err, fs.ErrNotExist) {
				continue
			}
			return nil, err
		}
		for _, ent := range ents {
			if ent.IsDir() || !ent.Type().IsRegular() || !strings.HasSuffix(ent.Name(), ".mworldpack") {
				continue
			}
			if !assets.ValidPack(dir, ent.Name()) {
				return nil, fmt.Errorf("%s: not a map pack name", filepath.Join(dir, ent.Name()))
			}
			info, err := ent.Info()
			if err != nil {
				return nil, err
			}
			objs = append(objs, &object{key: "static/" + dir + "/" + ent.Name(), path: filepath.Join(root, ent.Name()), size: info.Size(), pack: dir, rel: ent.Name()})
		}
	}
	// Chat action icons come from the first root only and are not manifest entries (the client never lists them).
	if first {
		chatDir := filepath.Join(dataset, "cache", "action")
		ents, err := os.ReadDir(chatDir)
		if err != nil {
			return nil, fmt.Errorf("cache/action: %w", err)
		}
		for _, ent := range ents {
			name, ok := strings.CutPrefix(ent.Name(), chatActionPrefix)
			if !ok || !assets.ChatActionFile(name) || !ent.Type().IsRegular() {
				continue
			}
			info, err := ent.Info()
			if err != nil {
				return nil, err
			}
			objs = append(objs, &object{key: "static/chatting/action_hd/" + name, path: filepath.Join(chatDir, ent.Name()), size: info.Size()})
		}
	}
	craft, err := craftObjects(dataset)
	if err != nil {
		return nil, err
	}
	objs = append(objs, craft...)
	for _, kind := range assets.ItemKinds {
		kindDir := filepath.Join(dataset, "item", kind)
		ents, err := os.ReadDir(kindDir)
		if err != nil {
			if !first && errors.Is(err, fs.ErrNotExist) {
				continue
			}
			return nil, err
		}
		for _, ent := range ents {
			// Only numeric folders are item ids; the client never requests any other name.
			if !ent.IsDir() || !isDigits(ent.Name()) {
				continue
			}
			idDir := filepath.Join(kindDir, ent.Name())
			err := filepath.WalkDir(idDir, func(p string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() || !d.Type().IsRegular() {
					return nil
				}
				info, err := d.Info()
				if err != nil {
					return err
				}
				rel := filepath.ToSlash(mustRel(idDir, p))
				key := "static/item/" + kind + "/" + ent.Name() + "/" + rel
				objs = append(objs, &object{key: key, path: p, size: info.Size()})
				return nil
			})
			if err != nil {
				return nil, err
			}
		}
	}
	return objs, nil
}

// craftObjects lists the Garden craft art of one dataset root (assets.CraftRel): the craft folder item/craftitem/ first,
// then the download cache cache/, both at the same relative path. A path both folders hold is listed once, from the
// craft folder, which is what cherry-assets serves in place when streaming is off (ServeGardenCraftArt). A missing
// folder contributes nothing.
func craftObjects(dataset string) ([]*object, error) {
	var objs []*object
	seen := map[string]bool{}
	for _, base := range []string{filepath.Join(dataset, "item", "craftitem"), filepath.Join(dataset, "cache")} {
		for _, dir := range assets.CraftDirs {
			root := filepath.Join(base, dir)
			if _, err := os.Stat(root); errors.Is(err, fs.ErrNotExist) {
				continue
			}
			err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() || !d.Type().IsRegular() {
					return nil
				}
				rel := filepath.ToSlash(mustRel(base, p))
				if _, ok := assets.CraftRel("/" + rel); !ok || seen[rel] {
					return nil
				}
				seen[rel] = true
				info, err := d.Info()
				if err != nil {
					return err
				}
				objs = append(objs, &object{key: "static/" + rel, path: p, size: info.Size()})
				return nil
			})
			if err != nil {
				return nil, fmt.Errorf("%s: %w", dir, err)
			}
		}
	}
	return objs, nil
}

// craftGroup names the plan group of a Garden craft object key ("craft:garden01"), or "" for any other key.
func craftGroup(key string) string {
	rel, ok := strings.CutPrefix(key, "static/")
	if !ok {
		return ""
	}
	if _, ok := assets.CraftRel("/" + rel); !ok {
		return ""
	}
	dir, _, _ := strings.Cut(rel, "/")
	return "craft:" + dir
}

// onlyPacks keeps the map pack objects.
func onlyPacks(objs []*object) []*object {
	var out []*object
	for _, o := range objs {
		if o.pack != "" {
			out = append(out, o)
		}
	}
	return out
}

func mustRel(base, p string) string {
	rel, err := filepath.Rel(base, p)
	if err != nil {
		panic(err) // both paths come from the same walk
	}
	return rel
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

// totals summarises the objects per group ("bulk:<cat>", "pack:<dir>", "chat:action", "craft:<dir>", "item:<kind>", "generated").
type totals struct {
	count map[string]int
	bytes map[string]int64
}

func summarize(objs []*object) totals {
	t := totals{count: map[string]int{}, bytes: map[string]int64{}}
	for _, o := range objs {
		var group string
		switch {
		case o.generated:
			group = "generated"
		case o.cat != "":
			group = "bulk:" + o.cat
		case o.pack != "":
			group = "pack:" + o.pack
		case craftGroup(o.key) != "":
			group = craftGroup(o.key)
		case strings.HasPrefix(o.key, "static/chatting/"):
			group = "chat:action"
		default:
			group = "item:" + strings.Split(o.key, "/")[2]
		}
		t.count[group]++
		t.bytes[group] += o.size
	}
	return t
}

func printPlan(objs []*object) {
	t := summarize(objs)
	groups := make([]string, 0, len(t.count))
	for g := range t.count {
		groups = append(groups, g)
	}
	sort.Strings(groups)
	var bulkN, packN, chatN, craftN, itemN, genN int
	var bulkB, packB, chatB, craftB, itemB, genB int64
	for _, g := range groups {
		fmt.Printf("%-16s %8d objects %14d bytes\n", g, t.count[g], t.bytes[g])
		switch {
		case strings.HasPrefix(g, "bulk:"):
			bulkN += t.count[g]
			bulkB += t.bytes[g]
		case strings.HasPrefix(g, "pack:"):
			packN += t.count[g]
			packB += t.bytes[g]
		case strings.HasPrefix(g, "chat:"):
			chatN += t.count[g]
			chatB += t.bytes[g]
		case strings.HasPrefix(g, "craft:"):
			craftN += t.count[g]
			craftB += t.bytes[g]
		case g == "generated":
			genN += t.count[g]
			genB += t.bytes[g]
		default:
			itemN += t.count[g]
			itemB += t.bytes[g]
		}
	}
	fmt.Printf("%-16s %8d objects %14d bytes\n", "bulk total", bulkN, bulkB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "pack total", packN, packB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "chat total", chatN, chatB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "craft total", craftN, craftB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "item total", itemN, itemB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "generated", genN, genB)
	fmt.Printf("%-16s %8d objects %14d bytes\n", "all", bulkN+packN+chatN+craftN+itemN+genN, bulkB+packB+chatB+craftB+itemB+genB)
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: cherry-assets plan|upload|verify|migrate-manifests [flags]")
		os.Exit(2)
	}
	cmd, args := os.Args[1], os.Args[2:]
	flags := flag.NewFlagSet(cmd, flag.ExitOnError)
	concurrency := flags.Int("concurrency", 8, "parallel R2 requests (upload)")
	forceD1 := flags.Bool("force-d1", false, "rewrite the D1 manifest rows even when they look current (upload)")
	packsOnly := flags.Bool("packs-only", false, "upload only the map packs and cherry/manifest/packs.json (upload)")
	zipFlag := flags.String("zip", thumbs.DpZipPath, "the 2014 iOS item.zip to convert (convert)")
	outFlag := flags.String("out", assets.GeneratedItemRoot, "the generated item tree: convert writes it, plan/upload read it")
	_ = flags.Parse(args)

	if cmd == "migrate-manifests" { // R2 only: it moves the existing indexes and never reads the dataset
		if err := runMigrate(context.Background()); err != nil {
			fail("migrate-manifests: %v", err)
		}
		return
	}
	if cmd == "convert" { // local only: the iOS-only items into the generated tree (no R2, no archive writes)
		if err := runConvert(*zipFlag, *outFlag); err != nil {
			fail("convert: %v", err)
		}
		return
	}
	objs, err := buildObjects(archiveRoots)
	if err != nil {
		fail("dataset: %v", err)
	}
	objs, err = withGenerated(objs, archiveRoots, *outFlag)
	if err != nil {
		fail("generated items: %v", err)
	}
	switch cmd {
	case "plan":
		printPlan(objs)
	case "upload":
		if *packsOnly {
			objs = onlyPacks(objs)
		}
		if err := runUpload(context.Background(), objs, *concurrency, *forceD1, *packsOnly); err != nil {
			fail("upload: %v", err)
		}
	case "verify":
		if err := runVerify(context.Background(), objs); err != nil {
			fail("verify: %v", err)
		}
	default:
		fail("unknown command %q", cmd)
	}
}

func fail(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "cherry-assets: "+format+"\n", args...)
	os.Exit(1)
}

// runMigrate moves the legacy manifest/ indexes to cherry/manifest/ (assets.MigrateManifests).
func runMigrate(ctx context.Context) error {
	cfg, err := loadR2()
	if err != nil {
		return err
	}
	return assets.MigrateManifests(ctx, assets.NewClient(cfg), func(msg string) { fmt.Println(msg) })
}

// credsPath is %LOCALAPPDATA%\Cherry\cloudflare.json.
func credsPath() (string, error) {
	base, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(base, "Cherry", "cloudflare.json"), nil
}

func loadR2() (assets.Config, error) {
	p, err := credsPath()
	if err != nil {
		return assets.Config{}, err
	}
	return assets.LoadConfig(p)
}
